   {
    "quote": "Tighten GENERATED expression restrictions on inherited and partitioned tables",
    "source": "PostgreSQL 16 release notes: Migration to Version 16",
    "release_of_change": "16"
   }
  ]
 },
 {
  "condition_id": "the_database_uses_inherited_or_partition_2730d6",
